<?php
require_once '../config/config.php';
require_once '../config/auth.php';

require_login('teacher');
$teacher_id=(int)$_SESSION['user_id'];
$q=$conn->prepare("SELECT e.*,s.name subject_name,COUNT(eq.question_id) question_count FROM exams e LEFT JOIN subjects s ON s.id=e.subject_id LEFT JOIN exam_questions eq ON eq.exam_id=e.id WHERE e.teacher_id=? GROUP BY e.id ORDER BY e.created_at DESC");$q->execute(array($teacher_id));$items=$q->fetchAll(PDO::FETCH_ASSOC);
$practice=count(array_filter($items,function($e){return $e['exam_type']==='Practice';}));$live=count($items)-$practice;
?>
