?> / <?=$i['required_question_count']?></td><td><?=$i['total_marks']?></td><td><?=$i['duration_minutes']?> min</td><td><span class="badge text-bg-<?=in_array($i['status'],array('Active','Live','Scheduled'))?'success':'secondary' ?>"><?=htmlspecialchars($i['status'])?></span></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="7" class="text-center text-muted py-5"><i class="fa-solid fa-file-circle-plus d-block fs-3 mb-2"></i>No exams created yet. Use Create Exam to publish your first test.</td></tr><?php endif; ?></tbody></table></div></section></main></div><script src="assets/js/exams.js" defer></script></body></html>
